// Prepare lead data for AI analysis
const lead = $input.first().json;

// Build comprehensive lead profile for AI
const profile = {
  leadId: lead.id,
  email: lead.email,
  name: `${lead.firstName || ''} ${lead.lastName || ''}`.trim(),
  company: lead.company,

  // Analyze email domain
  emailAnalysis: {
    domain: lead.email?.split('@')[1] || '',
    isBusinessEmail: !['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'aol.com'].includes(lead.email?.split('@')[1]?.toLowerCase()),
    isCorporate: lead.email?.includes(lead.company?.toLowerCase().replace(/[^a-z]/g, '')) || false
  },

  // Source & intent signals
  sourceSignals: {
    source: lead.source,
    isHighIntent: ['demo_request', 'pricing_page', 'contact_sales'].includes(lead.source),
    isOrganic: ['organic', 'direct', 'referral'].includes(lead.source)
  },

  // Data completeness score
  completeness: {
    hasFirstName: !!lead.firstName,
    hasLastName: !!lead.lastName,
    hasCompany: !!lead.company,
    hasPhone: !!lead.phone,
    score: [lead.firstName, lead.lastName, lead.company, lead.phone].filter(Boolean).length / 4
  },

  // Timestamp analysis
  timing: {
    capturedAt: lead.capturedAt,
    dayOfWeek: new Date(lead.capturedAt).toLocaleString('en-US', { weekday: 'long' }),
    isBusinessHours: (() => {
      const hour = new Date(lead.capturedAt).getHours();
      return hour >= 9 && hour <= 17;
    })()
  },

  rawLead: lead
};

return profile;

// Fallback scoring when AI fails
const profile = $('Code - Build Lead Profile').first().json;

let score = 50; // Base score

// Email quality
if (profile.emailAnalysis.isBusinessEmail) score += 15;
if (profile.emailAnalysis.isCorporate) score += 10;

// Data completeness
score += Math.floor(profile.completeness.score * 20);

// Source signals
if (profile.sourceSignals.isHighIntent) score += 10;

// Cap score at 100
score = Math.min(score, 100);

return {
  success: true,
  data: {
    score,
    confidence: 0.6,
    reasoning: 'Fallback rule-based scoring (AI unavailable)',
    signals: {
      positive: profile.emailAnalysis.isBusinessEmail ? ['Business email domain'] : [],
      negative: profile.completeness.score < 0.5 ? ['Incomplete profile'] : [],
      neutral: ['Fallback scoring applied']
    },
    recommendedAction: score >= 70 ? 'schedule_call' : 'nurture_sequence',
    fallback: true
  }
};

// Combine profile with AI qualification results
const profile = $('Code - Build Lead Profile').first().json;
const aiResult = $input.first().json;

const qualification = {
  leadId: profile.leadId,
  email: profile.email,
  name: profile.name,
  company: profile.company,

  // AI qualification results
  score: aiResult.data?.score || 0,
  confidence: aiResult.data?.confidence || 0,
  reasoning: aiResult.data?.reasoning || '',

  // Signals breakdown
  signals: aiResult.data?.signals || {},

  // Routing decision
  recommendedAction: aiResult.data?.recommendedAction || 'needs_review',

  // Qualification tier
  tier: (() => {
    const score = aiResult.data?.score || 0;
    if (score >= 80) return 'hot';
    if (score >= 60) return 'warm';
    if (score >= 40) return 'nurture';
    return 'cold';
  })(),

  // Metadata
  qualifiedAt: new Date().toISOString(),
  processingId: $execution.id,
  isFallback: aiResult.data?.fallback || aiResult.data?.mock || false
};

return qualification;
